INSERT INTO `diseases` (`disease_name`, `icd_code`, `category_path`, `description`, `symptoms`) VALUES
('普通感冒', 'J00', '呼吸系统>上呼吸道感染', '由病毒引起的上呼吸道感染性疾病，主要表现为鼻部症状。', '鼻塞,流涕,打喷嚏,咽痛,咳嗽,低热,头痛,乏力'),
('流行性感冒', 'J09', '呼吸系统>上呼吸道感染', '由流感病毒引起的急性呼吸道传染病，传染性强。', '高热,畏寒,头痛,肌肉酸痛,乏力,咳嗽,咽痛,流涕'),
('急性支气管炎', 'J20', '呼吸系统>下呼吸道感染', '支气管黏膜的急性炎症，多由病毒或细菌感染引起。', '咳嗽,咳痰,胸闷,气短,发热,咽痛,鼻塞'),
('慢性支气管炎', 'J40', '呼吸系统>慢性气道疾病', '气管支气管黏膜的慢性非特异性炎症，每年持续3个月以上。', '慢性咳嗽,咳痰,气短,胸闷,喘息,反复呼吸道感染'),
('支气管哮喘', 'J45', '呼吸系统>慢性气道疾病', '由多种细胞参与的气道慢性炎症性疾病，表现为可逆性气流受限。', '喘息,胸闷,气短,咳嗽,咳痰,夜间憋醒,呼气性呼吸困难'),
('肺炎', 'J18', '呼吸系统>下呼吸道感染', '终末气道、肺泡和肺间质的炎症，可由细菌、病毒等引起。', '高热,咳嗽,咳痰,胸痛,呼吸困难,乏力,寒战,铁锈色痰'),
('慢性阻塞性肺疾病', 'J44', '呼吸系统>慢性气道疾病', '具有气流阻塞特征的慢性支气管炎和（或）肺气肿。', '慢性咳嗽,咳痰,气短,呼吸困难,胸闷,喘息,体重下降'),
('过敏性鼻炎', 'J30', '呼吸系统>鼻部疾病', '特应性个体接触变应原后由IgE介导的鼻黏膜非感染性炎症。', '阵发性喷嚏,清水样涕,鼻塞,鼻痒,眼痒,流泪'),
('鼻窦炎', 'J01', '呼吸系统>鼻部疾病', '鼻窦黏膜的炎症性疾病，多由细菌感染引起。', '鼻塞,脓涕,头痛,嗅觉减退,发热,面部胀痛'),
('急性咽炎', 'J02', '呼吸系统>上呼吸道感染', '咽黏膜、黏膜下组织的急性炎症，多由病毒或细菌感染。', '咽部干燥,灼热,咽痛,吞咽困难,发热,头痛,食欲不振'),
('急性扁桃体炎', 'J03', '呼吸系统>上呼吸道感染', '扁桃体的急性非特异性炎症，常伴有轻重不一的咽炎。', '咽痛,吞咽困难,发热,畏寒,头痛,扁桃体肿大,咽部充血'),
('肺气肿', 'J43', '呼吸系统>慢性气道疾病', '终末细支气管远端气腔持久性扩张，伴有肺泡壁破坏。', '咳嗽,咳痰,气短,进行性呼吸困难,胸闷,桶状胸,乏力'),
('肺源性心脏病', 'I27', '呼吸系统>肺血管疾病', '由支气管肺组织或肺动脉血管病变所致肺动脉高压引起的心脏病。', '咳嗽,咳痰,气短,心悸,下肢水肿,颈静脉怒张,肝大'),
('急性呼吸窘迫综合征', 'J80', '呼吸系统>重症疾病', '由肺内或肺外原因引起的以顽固性低氧血症为特征的综合征。', '呼吸急促,发绀,呼吸困难,烦躁,焦虑,出汗,低氧血症'),
('间质性肺炎', 'J84', '呼吸系统>间质性疾病', '以肺间质炎症和纤维化为主要表现的一组疾病。', '进行性呼吸困难,干咳,乏力,体重下降,杵状指,发绀'),
('肺脓肿', 'J85', '呼吸系统>下呼吸道感染', '由多种病原菌引起的肺组织化脓性病变，形成含脓液的空腔。', '高热,咳嗽,咳大量脓臭痰,胸痛,乏力,消瘦,盗汗'),
('支气管扩张', 'J47', '呼吸系统>慢性气道疾病', '支气管及其周围组织慢性炎症导致支气管壁破坏，形成持久性扩张。', '慢性咳嗽,咳大量脓痰,反复咯血,胸闷,气短,杵状指'),
('急性胃炎', 'K29', '消化系统>胃部疾病', '由多种病因引起的急性胃黏膜炎症，表现为充血、水肿、糜烂。', '上腹痛,腹胀,恶心,呕吐,食欲不振,反酸,烧心'),
('慢性胃炎', 'K29', '消化系统>胃部疾病', '由多种病因引起的慢性胃黏膜炎性病变，是最常见的胃病。', '上腹痛,腹胀,反酸,嗳气,食欲不振,恶心,呕吐,消瘦'),
('胃溃疡', 'K25', '消化系统>胃部疾病', '胃黏膜被胃消化液自身消化而造成的超过黏膜肌层的组织损伤。', '周期性上腹痛,反酸,嗳气,烧心,腹胀,恶心,呕吐,黑便'),
('十二指肠溃疡', 'K26', '消化系统>肠道疾病', '十二指肠黏膜被消化液自身消化造成的超过黏膜肌层的损伤。', '空腹痛,夜间痛,进食缓解,反酸,嗳气,上腹胀,恶心,呕吐'),
('胃食管反流病', 'K21', '消化系统>食管疾病', '胃十二指肠内容物反流入食管引起烧心等症状，可引起食管黏膜损伤。', '烧心,反酸,胸骨后痛,吞咽困难,咽部异物感,咳嗽,哮喘'),
('反流性食管炎', 'K21', '消化系统>食管疾病', '由胃十二指肠内容物反流入食管引起的食管炎症性病变。', '烧心,反酸,胸骨后烧灼感,吞咽痛,吞咽困难,呕血,黑便'),
('急性肠炎', 'K52', '消化系统>肠道疾病', '由细菌、病毒、寄生虫等感染或饮食不当引起的急性肠道炎症。', '腹痛,腹泻,恶心,呕吐,发热,腹胀,肠鸣音亢进'),
('慢性肠炎', 'K52', '消化系统>肠道疾病', '肠道的慢性炎症性疾病，可由感染、免疫、遗传等因素引起。', '慢性腹痛,腹泻,腹胀,食欲不振,消瘦,乏力,黏液便'),
('溃疡性结肠炎', 'K51', '消化系统>肠道疾病', '一种病因不明的直肠和结肠慢性非特异性炎症性疾病。', '腹泻,黏液脓血便,腹痛,里急后重,发热,消瘦,贫血'),
('克罗恩病', 'K50', '消化系统>肠道疾病', '一种病因不明的胃肠道慢性炎性肉芽肿性疾病，多见于末段回肠。', '腹痛,腹泻,体重下降,发热,腹部包块,瘘管形成,肛周病变'),
('肠易激综合征', 'K58', '消化系统>功能性胃肠病', '以腹痛、腹胀、排便习惯改变为主要表现的功能性肠病。', '腹痛,腹胀,腹泻,便秘,腹泻便秘交替,排便不尽感,黏液便'),
('便秘', 'K59', '消化系统>肠道疾病', '指排便次数减少、粪便干硬和（或）排便困难。', '排便次数减少,粪便干硬,排便困难,腹胀,腹痛,食欲不振'),
('急性胰腺炎', 'K85', '消化系统>胰腺疾病', '多种病因导致胰酶在胰腺内被激活后引起胰腺组织自身消化的炎症。', '剧烈上腹痛,恶心,呕吐,发热,腹胀,黄疸,休克,腰背部放射痛'),
('慢性胰腺炎', 'K86', '消化系统>胰腺疾病', '由各种原因导致的胰腺局部或弥漫性的慢性进展性炎症。', '反复发作的上腹痛,向腰背部放射,消瘦,脂肪泻,糖尿病,消化不良'),
('急性胆囊炎', 'K81', '消化系统>胆道疾病', '由胆囊管梗阻、细菌感染等引起的胆囊急性炎症性疾病。', '右上腹痛,向右肩背部放射,发热,恶心,呕吐,墨菲征阳性,黄疸'),
('慢性胆囊炎', 'K81', '消化系统>胆道疾病', '胆囊持续的、反复发作的炎症过程，约90%合并胆囊结石。', '右上腹不适,隐痛,腹胀,嗳气,厌油腻,餐后饱胀,胆绞痛'),
('胆石症', 'K80', '消化系统>胆道疾病', '胆道系统（包括胆囊和胆管）的任何部位发生结石的疾病。', '胆绞痛,右上腹痛,黄疸,发热,寒战,恶心,呕吐,消化不良'),
('脂肪肝', 'K76', '消化系统>肝脏疾病', '由于各种原因引起的肝细胞内脂肪堆积过多的病变。', '乏力,肝区不适,腹胀,食欲不振,恶心,呕吐,肝大,体重增加'),
('病毒性肝炎', 'B15', '消化系统>肝脏疾病', '由多种肝炎病毒引起的以肝脏病变为主的传染病。', '乏力,食欲减退,恶心,呕吐,腹胀,肝区痛,黄疸,发热,尿色加深'),
('肝硬化', 'K74', '消化系统>肝脏疾病', '由一种或多种病因长期或反复作用形成的弥漫性肝损害。', '乏力,消瘦,腹胀,腹水,黄疸,蜘蛛痣,肝掌,脾大,出血倾向'),
('药物性肝损伤', 'K71', '消化系统>肝脏疾病', '由各类处方或非处方的化学药物、生物制剂等所诱发的肝损伤。', '乏力,食欲减退,腹胀,恶心,呕吐,黄疸,肝区痛,尿色加深'),
('吸收不良综合征', 'K90', '消化系统>肠道疾病', '由多种原因引起的营养物质不能被小肠正常吸收的临床综合征。', '腹泻,脂肪泻,腹胀,消瘦,乏力,营养不良,贫血,维生素缺乏'),
('消化道出血', 'K92', '消化系统>急诊疾病', '从食管到肛门之间的消化道出血，包括上消化道和下消化道出血。', '呕血,黑便,便血,头晕,心悸,乏力,血压下降,休克,贫血'),
('高血压', 'I10', '心血管系统>高血压', '以体循环动脉血压持续升高为主要表现的临床综合征。', '头晕,头痛,颈项发紧,疲劳,心悸,视物模糊,鼻出血,耳鸣'),
('冠状动脉粥样硬化性心脏病', 'I25', '心血管系统>冠状动脉疾病', '冠状动脉发生粥样硬化引起管腔狭窄或闭塞，导致心肌缺血缺氧或坏死。', '胸痛,胸闷,心悸,气短,出汗,恶心,呕吐,放射痛,活动后加重'),
('心绞痛', 'I20', '心血管系统>冠状动脉疾病', '冠状动脉供血不足，心肌急剧缺血缺氧所引起的以发作性胸痛为表现的综合征。', '胸骨后压榨痛,胸闷,气短,心悸,出汗,向左肩放射,活动诱发,休息缓解'),
('心肌梗死', 'I21', '心血管系统>急性冠脉综合征', '冠状动脉闭塞，血流中断，使部分心肌因严重持久性缺血而发生坏死。', '剧烈持久胸痛,压榨感,濒死感,大汗,烦躁,恶心,呕吐,心律失常,休克'),
('心力衰竭', 'I50', '心血管系统>心力衰竭', '由于心室功能不全引起的一种临床综合征，通常表现为收缩或舒张功能障碍。', '呼吸困难,气短,咳嗽,咳痰,下肢水肿,乏力,心悸,夜间阵发性呼吸困难'),
('心律失常', 'I49', '心血管系统>心律失常', '心脏冲动的频率、节律、起源部位、传导速度或激动次序的异常。', '心悸,胸闷,头晕,气短,乏力,黑矇,晕厥,脉搏不齐,心跳停顿感'),
('房颤', 'I48', '心血管系统>心律失常', '最常见的持续性心律失常，心房激动频率达300-600次/分。', '心悸,气短,胸闷,头晕,乏力,脉搏不齐,多尿,焦虑,晕厥'),
('高血压性心脏病', 'I11', '心血管系统>高血压', '长期高血压导致左心室肥厚、扩大，最终发展为心力衰竭的心脏病。', '头痛,头晕,心悸,气短,胸闷,下肢水肿,咳嗽,咳痰,乏力'),
('风湿性心脏病', 'I09', '心血管系统>瓣膜疾病', '由风湿热活动累及心脏瓣膜而造成的心脏瓣膜病变。', '心悸,气短,乏力,咳嗽,咯血,下肢水肿,呼吸困难,心脏杂音'),
('感染性心内膜炎', 'I33', '心血管系统>感染性疾病', '由细菌、真菌等微生物直接感染而产生心瓣膜或心室壁内膜的炎症。', '发热,心悸,乏力,贫血,杵状指,心脏杂音,栓塞现象,皮肤瘀斑'),
('主动脉夹层', 'I71', '心血管系统>主动脉疾病', '主动脉腔内的血液通过内膜破口进入主动脉壁中层而形成的血肿。', '撕裂样剧烈胸痛,放射痛,高血压,休克,焦虑,大汗,脉搏不对称'),
('心肌炎', 'I51', '心血管系统>心肌疾病', '心肌的局限性或弥漫性炎性病变，可由感染、免疫等因素引起。', '发热,乏力,心悸,胸闷,胸痛,呼吸困难,心律失常,心力衰竭,心源性休克'),
('心肌病', 'I42', '心血管系统>心肌疾病', '由不同病因引起的心肌病变导致心肌机械和（或）心电功能障碍。', '乏力,呼吸困难,心悸,胸闷,水肿,晕厥,心律失常,心脏扩大'),
('心包炎', 'I30', '心血管系统>心包疾病', '心包脏层和壁层的炎症，可由感染、自身免疫、物理化学等因素引起。', '胸痛,胸闷,呼吸困难,发热,心悸,心包摩擦音,颈静脉怒张,低血压'),
('外周动脉疾病', 'I73', '心血管系统>外周血管疾病', '除冠状动脉和脑血管以外的其他动脉狭窄、闭塞或瘤样扩张疾病。', '间歇性跛行,下肢疼痛,麻木,发凉,皮肤苍白,溃疡,坏疽,脉搏减弱'),
('静脉血栓', 'I82', '心血管系统>静脉疾病', '在静脉内形成的血凝块，可导致血管阻塞，常见于下肢深静脉。', '下肢肿胀,疼痛,皮温升高,皮肤发红,浅静脉扩张,低热,肺栓塞风险'),
('1型糖尿病', 'E10', '内分泌代谢>糖尿病', '胰岛β细胞破坏，导致胰岛素绝对缺乏所引起的糖尿病。', '多饮,多尿,多食,体重下降,乏力,口渴,视物模糊,酮症酸中毒'),
('2型糖尿病', 'E11', '内分泌代谢>糖尿病', '以胰岛素抵抗为主伴胰岛素相对不足，或胰岛素分泌不足为主伴胰岛素抵抗。', '多饮,多尿,多食,体重下降,乏力,口渴,视物模糊,皮肤瘙痒,伤口不愈合'),
('糖尿病酮症酸中毒', 'E10', '内分泌代谢>糖尿病急性并发症', '糖尿病患者在各种诱因作用下，胰岛素严重不足，升糖激素升高导致的代谢紊乱。', '多尿,口渴,乏力,食欲减退,恶心,呕吐,呼吸深快,烂苹果味,昏迷'),
('甲状腺功能亢进症', 'E05', '内分泌代谢>甲状腺疾病', '甲状腺合成释放过多甲状腺激素，造成机体代谢亢进和交感神经兴奋。', '心悸,多汗,多食,消瘦,易怒,手抖,突眼,甲状腺肿大,月经紊乱'),
('甲状腺功能减退症', 'E03', '内分泌代谢>甲状腺疾病', '甲状腺激素合成和分泌减少或组织利用不足导致的全身代谢减低综合征。', '乏力,怕冷,体重增加,嗜睡,便秘,皮肤干燥,脱发,月经不调,黏液性水肿'),
('亚急性甲状腺炎', 'E06', '内分泌代谢>甲状腺疾病', '与病毒感染有关的自限性甲状腺炎症，为最常见的甲状腺疼痛性疾病。', '甲状腺区疼痛,吞咽加重,发热,乏力,心悸,多汗,甲状腺肿大,压痛'),
('痛风', 'M10', '内分泌代谢>嘌呤代谢疾病', '由单钠尿酸盐沉积所致的晶体相关性关节病，与嘌呤代谢紊乱有关。', '突发关节红肿热痛,夜间加重,第一跖趾关节多见,痛风石,尿酸升高'),
('高尿酸血症', 'E79', '内分泌代谢>嘌呤代谢疾病', '在正常嘌呤饮食状态下，非同日两次空腹血尿酸水平超过正常值。', '血尿酸升高,可无症状,或关节痛,肾结石,痛风发作,尿酸性肾病'),
